# PowerShell script to generate duplicate preview for CSE Semester 3 sections A-G\n$jar = "C:\\Users\\anany\\.m2\\repository\\com\\h2database\\h2\\2.2.224\\h2-2.2.224.jar"\n$dbPath = "$PSScriptRoot\..\data\odysseus_db"\n$url = "jdbc:h2:file:$dbPath;MODE=PostgreSQL;DATABASE_TO_LOWER=TRUE;AUTO_SERVER=TRUE;DB_CLOSE_DELAY=-1"\n$sql = @"\nSELECT ta.id,\n       ta.batch_id,\n       b.name AS batch_name,\n       ta.subject_id,\n       s.code AS subject_code,\n       s.name AS subject_name,\n       ta.academic_year,\n       ta.semester,\n       ta.day_of_week,\n       ta.period_number,\n       ta.faculty_id,\n       f.name AS faculty_name,\n       ta.is_lab_block,\n       ta.activity_type\nFROM timetable_assignments ta\nJOIN batches b ON b.id = ta.batch_id\nJOIN subjects s ON s.id = ta.subject_id\nJOIN faculty f ON f.id = ta.faculty_id\nWHERE b.department = 'CSE' AND b.semester = 3 AND b.name IN ('A','B','C','D','E','F','G')\nORDER BY ta.batch_id, ta.subject_id, ta.day_of_week, ta.period_number, ta.is_lab_block, ta.activity_type;\n"@\n# Output CSV file path\n$outPath = "$PSScriptRoot\duplicate_preview.csv"\njava -cp $jar org.h2.tools.Shell -url $url -user sa -sql $sql -output $outPath -showHeaders true\n
